-- Composicao das units (FCA; BPAC11 = 1 ON + 2 PNA pela curadoria).
INSERT INTO unit_compositions (asset_id, share_class, quantity)
SELECT a.id, v.share_class, v.quantity
FROM (VALUES
    ('ALUP11', 'ON', 1),
    ('ALUP11', 'PN', 2),
    ('ALUP11F', 'ON', 1),
    ('ALUP11F', 'PN', 2),
    ('BPAC11', 'ON', 1),
    ('BPAC11', 'PNA', 2),
    ('BPAC11F', 'ON', 1),
    ('BPAC11F', 'PNA', 2),
    ('BRBI11', 'ON', 1),
    ('BRBI11', 'PN', 2),
    ('BRBI11F', 'ON', 1),
    ('BRBI11F', 'PN', 2),
    ('ENGI11', 'ON', 1),
    ('ENGI11', 'PN', 4),
    ('ENGI11F', 'ON', 1),
    ('ENGI11F', 'PN', 4),
    ('IGTI11', 'ON', 1),
    ('IGTI11', 'PN', 2),
    ('IGTI11F', 'ON', 1),
    ('IGTI11F', 'PN', 2),
    ('KLBN11', 'ON', 1),
    ('KLBN11', 'PN', 4),
    ('KLBN11F', 'ON', 1),
    ('KLBN11F', 'PN', 4),
    ('SANB11', 'ON', 1),
    ('SANB11', 'PN', 1),
    ('SANB11F', 'ON', 1),
    ('SANB11F', 'PN', 1),
    ('SAPR11', 'ON', 1),
    ('SAPR11', 'PN', 4),
    ('SAPR11F', 'ON', 1),
    ('SAPR11F', 'PN', 4),
    ('TAEE11', 'ON', 1),
    ('TAEE11', 'PN', 2),
    ('TAEE11F', 'ON', 1),
    ('TAEE11F', 'PN', 2)
) AS v(ticker, share_class, quantity)
JOIN assets a ON a.ticker = v.ticker
ON CONFLICT (asset_id, share_class) DO UPDATE SET quantity = EXCLUDED.quantity;
